WITH valid AS (SELECT id, order_id, method, paid_at, CASE WHEN status IN ('REFUNDED', 'SUCCESS') THEN 'Core' ELSE 'Other' END AS status_group, COALESCE(method, 'OTHER') AS resolved_method FROM payments WHERE paid_at > DATE '2023-06-29'), gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM valid), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN burst_id >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS burst_id_tier, MAX(is_new_burst) FILTER (WHERE method = 'promptpay') AS promptpay_max_is_new_burst, MIN(paid_at) AS started_at, ROUND(AVG(is_new_burst), 2) AS avg_is_new_burst, MAX(paid_at) AS ended_at FROM islands GROUP BY CASE WHEN burst_id >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END
